// NativR-only step accounting: charge the selected string before conversion, leave later cells
// unvisited, and preserve the existing binding/session after a resource rejection.
it("bounds selected limit conversion work and recovers without inspecting later cells", async () => {
  const r = await createR({ execution: "inline", assets, limits: { maxSteps: 300 } });
  try {
    const longNumber = "9".repeat(100000);
    await r.assign("ownedLimits", ["1", longNumber]);
    expect(
      await r.eval(
        'identical(parse(text="11L;22L",n=ownedLimits,keep.source=FALSE),expression(11L))',
      ),
    ).toBe(true);
    await r.eval("retained<-expression(17L);NULL");
    await r.assign("ownedLimits", [longNumber, "1"]);
    await expect(
      r.eval('retained<-parse(text="11L;22L",n=ownedLimits,keep.source=FALSE)'),
    ).rejects.toMatchObject({ code: "NRL4001" });
    expect(await r.eval("identical(retained,expression(17L))&&sys.nframe()==0L")).toBe(true);
    expect(await r.eval('eval(parse(text="23L",n=1L,keep.source=FALSE))')).toBe(23);
  } finally {
    await r.dispose();
  }
});
